    const { window, nav } = createTestHarness();
    const heroPlayBtn = window.document.getElementById('hero-play-btn');
    const heroDetailsBtn = window.document.getElementById('hero-details-btn');
    const shelf1Cards = window.document.querySelectorAll('#shelf-providers .card-provider');
