    nav.setFocus(card0);
    nav.resetThrottle();
    const targetCard0 = nav.move('up');
    assert(targetCard0 === heroPlayBtn, `Up from Card 0 should land on heroPlayBtn. Got ${targetCard0?.id}`);

    // Card 1 (Prime Video, left: 280, center X: 360): collinear with hero-details-btn (left: 292, center X: 362)
    const card1 = shelf1Cards[1];
    nav.setFocus(card1);
    nav.resetThrottle();
    const targetCard1 = nav.move('up');
    assert(targetCard1 === heroDetailsBtn, `Up from Card 1 should land on heroDetailsBtn. Got ${targetCard1?.id}`);

    // Card 3 (Apple TV+, left: 648, center X: 728): collinear with #top header pills (left: 790, center X: 840)
    const card3 = shelf1Cards[3];
    nav.setFocus(card3);
    nav.resetThrottle();
    const targetCard3 = nav.move('up');
    assert(targetCard3.closest('#top') !== null, `Up from laterally offset Card 3 should route geometrically to #top. Got ${targetCard3?.id}`);
